//! Runtime of the shared mock distribution.
//!
//! This is the normal-library half of the mock distribution; the proc-macro
//! half lives in `xbin-mock-distro`. It owns the process-global [`MockSystem`]
//! that stands in for a project's shared-memory regions and re-exports the
//! in-tree runtime items the generated code refers to, so a fixture
//! application only depends on this crate and the generated `ipc-types`. The
//! `RticSwTask` trait the receivers implement is generated by the software
//! pass bound in `xbin-mock-distro` (M6.5-T5), not defined here.
//!
//! Because the system is process-global, applications expanded into one
//! process share the same regions while each gets the backend handle of its
//! own core through [`backend_for`].

use std::sync::LazyLock;

pub use rticx_xbin_mock::{MockBackend, MockSystem};
pub use rticx_xbin_rt as xbin_rt;

/// The fixtures' IPC regions, in process memory.
///
/// The regions are declared with the same `(source, target)` pairs as the
/// fixtures' `rticx.toml`; the mock ignores the declared addresses and sizes
/// and uses the backing array's own. The runtime is shared by every fixture,
/// so it carries the union of the directions they use: `0->1` for the
/// two-application end-to-end fixture, and all six directions of the
/// three-application fixture's fully connected `0<->1`, `1<->2`, `0<->2`
/// topology. A fixture only ever looks up the directions it declared, so the
/// extra regions are inert.
pub fn system() -> &'static MockSystem {
    static SYSTEM: LazyLock<MockSystem> = LazyLock::new(|| {
        let mut system = MockSystem::new();
        system
            .add_region(0, 1, 4096)
            .expect("the fixtures declare the `0->1` region");
        system
            .add_region(1, 0, 4096)
            .expect("the three-application fixture declares the `1->0` region");
        system
            .add_region(2, 1, 4096)
            .expect("the three-application fixture declares the `2->1` region");
        system
            .add_region(1, 2, 4096)
            .expect("the three-application fixture declares the `1->2` region");
        system
            .add_region(0, 2, 4096)
            .expect("the three-application fixture declares the `0->2` region");
        system
            .add_region(2, 0, 4096)
            .expect("the three-application fixture declares the `2->0` region");
        system
    });
    &SYSTEM
}

/// Returns the backend handle of global core `core`.
pub fn backend_for(core: u32) -> MockBackend {
    system().backend(core)
}
